    maya_q9_complete: { stat: "charisma", min: 13 },
    // Noelle — guarded; she needs you steady, not charming
    noelle_q2_complete: { stat: "confidence", min: 3 },
    noelle_q4_complete: { stat: "confidence", min: 5 },
    noelle_q5_complete: { stat: "confidence", min: 8 },
    // Third act. The mark she can't argue with, then the spreadsheet she
