  function statGateMet(flag) {
    const g = QUEST_STAT_GATES[flag];
    if (!g) return true;
    return ((state.stats && state.stats[g.stat]) || 0) >= g.min;
  }
  function statGateLabel(flag) {
    const g = QUEST_STAT_GATES[flag];
    if (!g) return null;
    const have = (state.stats && state.stats[g.stat]) || 0;
    return `${PLAYER_STAT_DEFS[g.stat].name} ${have}/${g.min}`;
  }
  function emptyStats() {
    const out = {};
    PLAYER_STAT_IDS.forEach((id) => { out[id] = 0; });
    return out;
  }
  /* Dialogue choices are tagged with a tone, not a stat, and for a long
     time those tags scored nothing — which left charisma, confidence and
     intelligence with no source anywhere in the game outside the dev and
     cheat panels. Every quest gate reads those three, so a player without
     the cheat code couldn't clear a single one. The tone a player reaches
     for IS the thing being practised, so the tags map straight onto it. */
  const TONE_STATS = { bold: "confidence", warm: "charisma", witty: "intelligence" };
  function grantStat(statId, amount) {
    const id = TONE_STATS[statId] || statId;
    if (!id || !PLAYER_STAT_DEFS[id]) return;
    if (!state.stats) state.stats = emptyStats();
    const before = state.stats[id] || 0;
    state.stats[id] = Math.max(0, Math.min(STAT_CAP, before + (amount || 0)));
    return state.stats[id] !== before;
  }

  /* Grants a stat and tells the player it happened. Silent points would
     read as nothing changing, and these are the numbers every quest gate
     in the game is measured against — the player has to be able to see
     them moving, and to see when a level name changes. */
  function noteStatGain(statId, amount) {
    const id = TONE_STATS[statId] || statId;
    const def = PLAYER_STAT_DEFS[id];
    if (!def) return;
    const before = (state.stats && state.stats[id]) || 0;
    if (!grantStat(id, amount)) return;
    const after = state.stats[id];
    const levelUp = statLevelName(id, after) !== statLevelName(id, before);
    showToast(levelUp ? `${def.name} → ${statLevelName(id, after)}` : `+${after - before} ${def.name}`, "bond");
    renderSidebar();
  }

  /* Every companion has a single portrait, used everywhere.
     charPortrait() picks the right file for the active mode. */
  function charPortrait(char) {
    if (!char) return "";
    return blackedModeOn() && char.blackedPortrait ? char.blackedPortrait : char.portrait;
  }
  function portraitHTML(charId, cls) {
    const char = DATA.characters[charId];
    if (!char) return "";
    return `<img class="${cls}" src="${charPortrait(char)}" alt="">`;
  }

  const $ = (id) => document.getElementById(id);

  /* ---------------- inline UI icons ----------------
     Copies of the SVGs in assets/icons/, inlined so there's no extra
     request per icon and nothing to cache separately. They're referenced
     by name because some (the lock especially) appear in a dozen places,
     and pasting markup at each site would be unmaintainable.
     Redraw a file in assets/icons/ and the copy here needs updating too. */
