  function demoCuts(flag) { return isDemo() && DEMO_CUT_FLAGS.indexOf(flag) !== -1; }
  /* Run once at boot: drop the cut steps from every quest log, and the
     action2 clips from the gallery, so nothing advertises what isn't
     there. */
  function applyDemoCuts() {
    if (!isDemo()) return;
    Object.keys(CHARACTER_QUEST_LOG).forEach((id) => {
      const log = CHARACTER_QUEST_LOG[id];
      if (log && log.steps) log.steps = log.steps.filter((s) => DEMO_CUT_FLAGS.indexOf(s.flag) === -1);
    });
    for (let i = MEDIA_CATALOG.length - 1; i >= 0; i--) {
      if (/\/action ?2\//i.test(MEDIA_CATALOG[i].ref || "")) MEDIA_CATALOG.splice(i, 1);
    }
    NEWS.unshift({
      id: "demo_notice",
      kind: "next",
      date: "You're playing the demo",
      title: "This is the demo build",
      lead: "Everything here is the real game — it just stops one scene short of the end.",
      body: [
        "All eight storylines are playable start to finish, with every quest, every job and every date they normally have.",
        "What's missing is the last scene of each arc: the evening each one has been building toward. Those eight scenes are the only thing cut, and they're what makes the full download four times this size.",
        "The full version is free. It lives on Patreon, along with release news and early builds of whatever's coming next."
      ]
    });
  }

