  const NTR_RIVALS = { serena: "Marcus", kira: "Tyler", valentina: "Ethan", harper: "Derek" };
  const NTR_LOCK_ICON = '<svg viewBox="0 0 14 14" style="width:14px;height:14px;vertical-align:-2px;display:inline-block;" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="6" width="8" height="7" rx="1.5" fill="#888"/><path d="M5 6V4.5a2 2 0 014 0V6" fill="none" stroke="#888" stroke-width="1.5"/><circle cx="7" cy="9.5" r="1" fill="#555"/></svg>';

  function ntrCorruption(charId) {
    return (state.ntrCorruption && state.ntrCorruption[charId]) || 0;
  }
  function addNtrCorruption(charId, amount) {
    if (!state.ntrCorruption) state.ntrCorruption = {};
    var old = state.ntrCorruption[charId] || 0;
    var val = Math.min(100, Math.max(0, old + amount));
    state.ntrCorruption[charId] = val;
    var milestone = NTR_CORRUPTION_MILESTONES.find(function(m) { return old < m && val >= m; });
    if (milestone) {
      var cName = DATA.characters[charId] ? DATA.characters[charId].name : charId;
      showToast(cName + " — Corruption " + milestone + "%");
    }
  }
  function ntrCorruptionTier(charId) {
    var c = ntrCorruption(charId);
    if (c >= 80) return "Corrupted";
    if (c >= 60) return "Falling";
    if (c >= 40) return "Wavering";
    if (c >= 20) return "Curious";
    return "Innocent";
  }
  function ntrPseudoQuests() {
    if (!state.flags.ntr_intro_complete) {
      return [{ title: "Welcome", note: "Look around and meet the household.", charId: "serena" }];
    }
    var items = [];
    NTR_CHARS.forEach(function(id) {
      var step = ntrQuestStep(id);
      var quests = DATA.ntrQuests[id];
      if (!quests) return;
      var quest = quests[step];
      if (!quest) return;
      if (quest.lines.length === 0) return;
      if (state.flags[quest.completionFlag]) return;
      var corr = ntrCorruption(id);
      var cName = DATA.characters[id] ? DATA.characters[id].name : id;
      if (corr < quest.corruptionRequired) {
        items.push({ title: quest.title, note: cName + " isn’t ready yet. Corruption: " + corr + "/" + quest.corruptionRequired + ".", charId: id });
      } else {
        var rm = quest.room ? roomTitle(quest.room) : scheduleRoomAt(id, quest.timeStart, quest.timeEnd);
        items.push({ title: quest.title, note: "Find " + cName + " at " + rm + " (" + quest.timeStart + ":00–" + quest.timeEnd + ":00).", charId: id });
      }
    });
    if (DATA.ntrNetorareQuests) {
      NTR_CHARS.forEach(function(id) {
        var rQuests = DATA.ntrNetorareQuests[id];
        if (!rQuests) return;
        var rStep = netorareStep(id);
        var rQuest = rQuests[rStep];
        if (!rQuest) return;
        if (state.flags[rQuest.completionFlag]) return;
        if (rQuest.preRequisiteFlag && !state.flags[rQuest.preRequisiteFlag]) return;
        var rival = DATA.ntrRivals && DATA.ntrRivals[id];
        var rivalName = rival ? rival.name : "Someone";
        var rm = rQuest.room ? roomTitle(rQuest.room) : scheduleRoomAt(id, rQuest.timeStart, rQuest.timeEnd);
        items.push({ title: "\u26A0 " + rQuest.title, note: rivalName + " is making moves. Check " + rm + " (" + rQuest.timeStart + ":00\u2013" + rQuest.timeEnd + ":00).", charId: id });
      });
    }
    return items;
  }
  function ntrQuestStep(charId) {
    return (state.ntrQuestProgress && state.ntrQuestProgress[charId]) || 0;
  }
  function advanceNtrQuest(charId) {
    if (!state.ntrQuestProgress) state.ntrQuestProgress = {};
    state.ntrQuestProgress[charId] = (state.ntrQuestProgress[charId] || 0) + 1;
  }
  function ntrRivalInfluence(charId) {
    return (state.ntrRivalInfluence && state.ntrRivalInfluence[charId]) || 0;
  }
  function setupNtrQuestJump(charId, targetStep) {
    state.flags.ntr_intro_complete = true;
    state.flags.tutorialFreed = true;
    state.flags.houseHubUnlocked = true;
    if (!state.ntrQuestProgress) state.ntrQuestProgress = {};
    if (!state.ntrCorruption) state.ntrCorruption = {};
    state.ntrQuestProgress[charId] = targetStep;
    var quests = DATA.ntrQuests[charId] || [];
    var cumCorr = 0;
    for (var i = 0; i < targetStep && i < quests.length; i++) {
      if (quests[i].completionFlag) state.flags[quests[i].completionFlag] = true;
      cumCorr += quests[i].corruptionReward || 0;
    }
    state.ntrCorruption[charId] = Math.max(state.ntrCorruption[charId] || 0, cumCorr);
    var quest = quests[targetStep];
    if (quest && quest.timeStart != null) {
      state.hour = quest.timeStart;
      state.minute = 0;
    }
  }
  function advanceNtrRivals() {
    if (!ntrModeOn()) return;
    if (!state.ntrRivalInfluence) state.ntrRivalInfluence = {};
    NTR_CHARS.forEach(function(id) {
      var cur = state.ntrRivalInfluence[id] || 0;
      var tick = 1 + Math.floor(cur / 30);
      state.ntrRivalInfluence[id] = Math.min(100, cur + tick);
    });
  }
  function checkNtrRivalEvent() {
    if (!ntrModeOn()) return null;
    var eligible = NTR_CHARS.filter(function(id) {
      var corr = ntrCorruption(id);
      var rival = ntrRivalInfluence(id);
      var chance = 0.05 + (corr / 1000) + (rival / 1000);
      return Math.random() < Math.min(chance, 0.30);
    });
    if (eligible.length === 0) return null;
    return eligible[Math.floor(Math.random() * eligible.length)];
  }
  function maybePlayNtrRivalEvent() {
    if (!ntrModeOn()) return false;
    var charId = checkNtrRivalEvent();
    if (!charId) return false;
    var events = DATA.ntrRivalEvents && DATA.ntrRivalEvents[charId];
    if (!events || !events.length) return false;
    var corr = ntrCorruption(charId);
    var best = null;
    for (var i = 0; i < events.length; i++) {
      if (corr >= events[i].minCorruption && !state.ntrWitnessed[events[i].id]) best = events[i];
    }
    if (!best) return false;
    state.ntrWitnessed[best.id] = true;
    addNtrCorruption(charId, 3);
    playSequence(best.lines, finishAfter);
    return true;
  }
  function ntrStatusLabel(charId) {
    var corr = ntrCorruption(charId);
    var step = ntrQuestStep(charId);
    if (step >= 4) return "Devoted";
    if (corr >= 80) return "Corrupted";
    if (corr >= 60) return "Falling";
    if (corr >= 40) return "Wavering";
    if (corr >= 20) return "Curious";
    return "Innocent";
  }

  /* ---- Netorare (rival quest) tracking ---- */
  function netorareStep(charId) {
    return (state.ntrNetorareProgress && state.ntrNetorareProgress[charId]) || 0;
  }
  function advanceNetorareStep(charId) {
    if (!state.ntrNetorareProgress) state.ntrNetorareProgress = {};
    state.ntrNetorareProgress[charId] = (state.ntrNetorareProgress[charId] || 0) + 1;
  }
  function maybePlayNetorareQuest() {
    if (!ntrModeOn()) return false;
    if (!DATA.ntrNetorareQuests) return false;
    var roomId = state.room;
    for (var i = 0; i < NTR_CHARS.length; i++) {
      var charId = NTR_CHARS[i];
      var quests = DATA.ntrNetorareQuests[charId];
      if (!quests) continue;
      var step = netorareStep(charId);
      var quest = quests[step];
      if (!quest) continue;
      if (quest.room !== roomId) continue;
      if (state.hour < quest.timeStart || state.hour >= quest.timeEnd) continue;
      if (quest.preRequisiteFlag && !state.flags[quest.preRequisiteFlag]) continue;
      if (state.flags[quest.completionFlag]) continue;
      state.flags[quest.completionFlag] = true;
      advanceNetorareStep(charId);
      addNtrCorruption(charId, 5);
      playSequence(quest.lines, finishAfter);
      return true;
    }
    return false;
  }


